/* AIVIC_FUNCTION_BUNDLE_START owner=validateMealRejectReason exports=validateMealRejectReason */
const __aivicBundle_56_validateMealRejectReason = (() => {
  function validateMealRejectReason(reason: string): {
    isValid: boolean;
    errorMessage: string;
    isSubmittable: boolean;
  } {
    // 入力が文字列であることを確認
    if (typeof reason !== 'string') {
      return {
        isValid: false,
        errorMessage: 'Reason must be a string',
        isSubmittable: false,
      };
    }
  
    // 1文字以上255文字以下の長さチェック
    if (reason.length < 1 || reason.length > 255) {
      return {
        isValid: false,
        errorMessage: 'Reason must be between 1 and 255 characters',
        isSubmittable: false,
      };
    }
  
    // 制御文字を含まないかチェック
    // 制御文字: U+0000～U+001F（改行・タブ除く）と U+007F（DEL）
    const controlCharPattern = /[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/;
    if (controlCharPattern.test(reason)) {
      return {
        isValid: false,
        errorMessage: 'Reason contains invalid control characters',
        isSubmittable: false,
      };
    }
  
    // すべての検証に合格
    return {
      isValid: true,
      errorMessage: '',
      isSubmittable: true,
    };
  }
  return { validateMealRejectReason };
})();
