const __aivicBundle_61_classifyRejectReason = (() => {
  interface ClassifyRejectReasonInput {
    reasonText: string;
    timestamp: Date;
  }
  
  interface ClassifyRejectReasonOutput {
    category: string;
    confidence: number;
    isAnomalous: boolean;
    requiresManualReview?: boolean;
    alternativeCategories?: string[];
    timestamp?: Date;
  }
  
  const classifyRejectReasonCategoryKeywords: Record<string, string[]> = {
    "栄養": ["栄養", "バランス", "栄養バランス"],
    "健康・栄養": ["塩分", "糖分", "脂肪", "コレステロール", "カロリー"],
    "アレルギー": ["アレルギー", "アレルゲン", "含まれている"],
    "調理時間": ["調理", "時間", "長すぎ", "手間"],
    "嗜好": ["嫌", "好み", "好きじゃない", "苦手"],
  };
  
  function classifyRejectReason(
    input: ClassifyRejectReasonInput
  ): ClassifyRejectReasonOutput {
    const { reasonText, timestamp } = input;
  
    // 異常値検出
    const isAnomalous =
      reasonText.trim().length === 0 ||
      reasonText.length > 1000 ||
      /^[!@#$%^&*()_+=\[\]{};:'",.<>?/\\|`~\s]*$/.test(reasonText);
  
    if (isAnomalous && reasonText.trim().length === 0) {
      return {
        category: "不明",
        confidence: 0,
        isAnomalous: true,
        timestamp,
      };
    }
  
    if (isAnomalous && /^[!@#$%^&*()_+=\[\]{};:'",.<>?/\\|`~\s]*$/.test(reasonText)) {
      return {
        category: "不明",
        confidence: 0.3,
        isAnomalous: true,
        timestamp,
      };
    }
  
    if (isAnomalous && reasonText.length > 1000) {
      return {
        category: "不明",
        confidence: 0.2,
        isAnomalous: true,
        timestamp,
      };
    }
  
    // キーワードマッチングによるカテゴリ分類
    const lowerText = reasonText.toLowerCase();
    const categoryScores: Record<string, number> = {};
  
    for (const [category, keywords] of Object.entries(
      classifyRejectReasonCategoryKeywords
    )) {
      let score = 0;
      for (const keyword of keywords) {
        if (lowerText.includes(keyword.toLowerCase())) {
          score += 1;
        }
      }
      if (score > 0) {
        categoryScores[category] = score;
      }
    }
  
    // 最高スコアのカテゴリを選択
    let bestCategory = "不明";
    let bestScore = 0;
    const alternativeCategories: string[] = [];
  
    for (const [category, score] of Object.entries(categoryScores)) {
      if (score > bestScore) {
        if (bestCategory !== "不明") {
          alternativeCategories.push(bestCategory);
        }
        bestCategory = category;
        bestScore = score;
      } else if (score === bestScore && score > 0) {
        alternativeCategories.push(category);
      }
    }
  
    // 信頼度スコアの計算
    let confidence = 0;
    if (bestCategory === "不明") {
      confidence = 0.3;
    } else if (bestScore >= 2) {
      confidence = 0.95;
    } else if (bestScore === 1) {
      confidence = 0.75;
    }
  
    // 曖昧な場合の信頼度調整
    if (
      reasonText.includes("なんか") ||
      reasonText.includes("なんとなく") ||
      reasonText.includes("よくわからない")
    ) {
      confidence = Math.min(confidence, 0.6);
    }
  
    const requiresManualReview = confidence < 0.7;
  
    return {
      category: bestCategory,
      confidence,
      isAnomalous: false,
      requiresManualReview,
      alternativeCategories:
        alternativeCategories.length > 0 ? alternativeCategories : undefined,
      timestamp,
    };
  }
  return { classifyRejectReason };
})();
